import sqlite3
from storage import connect

class OrderService:
    def __init__(self, db):
        self.db = db

    def seed(self, sku, qty):
        if not isinstance(sku, str) or sku == "":
            raise ValueError("sku must be a non‑empty string")
        if not isinstance(qty, int) or isinstance(qty, bool):
            raise ValueError("qty must be an integer")
        if qty < 0:
            raise ValueError("qty cannot be negative")
        self.db.execute('INSERT INTO stock VALUES (?,?)', (sku, qty))
        self.db.commit()

    def place(self, request_id, sku, qty):
        # ----- Parameter validation -----
        if not isinstance(request_id, str) or request_id == "":
            raise ValueError("request_id must be a non‑empty string")
        if not isinstance(sku, str) or sku == "":
            raise ValueError("sku must be a non‑empty string")
        if not isinstance(qty, int) or isinstance(qty, bool):
            raise ValueError("qty must be an integer")
        if qty <= 0:
            raise ValueError("quantity must be positive")

        # ----- Idempotency handling -----
        existing = self.db.execute(
            'SELECT sku, qty FROM orders WHERE request_id = ?', (request_id,)
        ).fetchone()
        if existing:
            existing_sku, existing_qty = existing
            if existing_sku == sku and existing_qty == qty:
                # Exact repeat – treat as success without side effects
                return True
            else:
                # Conflicting payload for the same idempotency key
                raise ValueError("conflicting idempotency key with different payload")

        # ----- Transactional stock reservation and outbox write -----
        try:
            self.db.execute('BEGIN')
            row = self.db.execute(
                'SELECT available FROM stock WHERE sku = ?', (sku,)
            ).fetchone()
            if not row or row[0] < qty:
                # Not enough stock – rollback and report failure
                self.db.execute('ROLLBACK')
                return False

            # Reserve stock
            self.db.execute(
                'UPDATE stock SET available = available - ? WHERE sku = ?', (qty, sku)
            )
            # Record order
            self.db.execute(
                'INSERT INTO orders (request_id, sku, qty, status) VALUES (?,?,?,?)',
                (request_id, sku, qty, 'placed')
            )
            # Write outbox event
            self.db.execute(
                'INSERT INTO outbox (event_id, kind, payload) VALUES (?,?,?)',
                (request_id, 'order_placed', sku)
            )
            self.db.execute('COMMIT')
            return True
        except Exception:
            # Ensure no partial state remains
            self.db.execute('ROLLBACK')
            raise

    def available(self, sku):
        return self.db.execute('SELECT available FROM stock WHERE sku = ?', (sku,)).fetchone()[0]

    def event_count(self):
        return self.db.execute('SELECT count(*) FROM outbox').fetchone()[0]

